    ((r.files || []).length ? '<div style="margin-top:6px">紀錄表原檔：' + r.files.map(f => '<button class="b" data-fid="' + esc(f.檔案ID) + '" data-fn="' + esc(f.檔名) + '" style="padding:1px 8px;font-size:12px;margin:2px">📎 ' + esc(f.檔名) + '</button>').join('') + '</div>' : '') +
    (has('督導紀錄編輯') ? '<div class="cnt">按下方「督導紀錄 →」可上傳紀錄表、查閱或修改結果。</div>' : '');
/* 下載已上傳的紀錄表原檔 */
$('resList').addEventListener('click', async e => {
  const b = e.target.closest('[data-fid]'); if (!b) return;
  b.disabled = true;
  try {
    const f = await api('djFile', { fileId: b.dataset.fid });
    const bin = atob(f.base64), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
    saveBlob(new Blob([u], { type: f.mimeType || 'application/octet-stream' }), f.name || b.dataset.fn);
  } catch (err) { toast('下載失敗：' + errMsg(err), 4000); }
  b.disabled = false;
});
